-- +goose Up
-- Запись релиза в журнал (notified_at NULL — бот уведомит админа на старте).
-- +goose StatementBegin
INSERT INTO releases (version, released_on, title, public_notes, tech_notes) VALUES (
  '2.124.0',
  '2026-10-29',
  'Пульт ТВ: папки под кодом, создание папок и загрузка файлов по одному',
  E'В медиатеке появились **папки под кодом**. Закрытая папка не видна вовсе: ни плиткой в разделе, ни строкой внутри альбома — и открыть её по прямой ссылке тоже нельзя. Прятать можно папки музыки и фото: и альбом целиком, и подпапку внутри него.\n\nЧтобы открыть, в заголовке раздела «Музыка» или «Фото и видео» нажмите **«🔓»** и наберите код. Какую папку открыть, решает сам код — поэтому у каждой папки он свой, и двух одинаковых не бывает. Рядом появится «🔒 Закрыть»: она убирает открытое сразу, а само оно закроется через полчаса, если папкой не пользоваться. Открыли на телефоне — на телевизоре папка осталась закрытой.\n\nКод ставится в админке, в разделе **«Папки под кодом»**: выбираете папку, задаёте код от 4 до 12 цифр. На диске при этом ничего не меняется, и в самой админке папка видна всегда — у неё свой PIN. Подсмотреть код потом нельзя, только задать заново или снять.\n\nВ «Медиатеке» у разделов «Музыка» и «Фото и видео» теперь три кнопки вместо одной. **«📁 Создать папку»** — пустая папка под новый альбом; внутри неё можно создавать подпапки. **«📦 ZIP альбомом»** — как раньше, архив целиком. **«📥 В папку…»** — выбрать существующую папку или подпапку и загрузить в неё файлы по одному, архив или музыку по ссылке.',
  E'locks.go. Закрытое не отдаёт САМ агент: `s.visible(path, r)` стоит в `/api/catalog` (`openTiles`), `/api/browse` (`hideLocked`), `/api/photos`, `/api/tracks`, `/api/playlists/{id}`, `/api/item`, `/media/{id}`, `/photo/{id}`, `/poster/{id}`. Прятать на странице было бы бессмысленно: id — хеш пути, подпись `k` считается от него же, и один раз увиденная ссылка работала бы всегда.\n\n`POST /api/unlock {pin}` ищет папку ПО коду (`lockStore.match`, сравнение всех записей до конца — время ответа не зависит от того, угадали ли первые цифры), поэтому коды у папок разные и одинаковые агент не даёт поставить. Списка закрытых папок наружу нет никогда. Билет — кука сеанса `htv_unlock` (HttpOnly, Path=base): её носит браузер сам, и не пришлось дописывать билет в каждый `<img src>` и `<video src>`, где заголовок не поставить; заголовок `X-Unlock` и параметр `u` тоже принимаются. Срок — `unlockIdle` 30 минут без обращений (каждое обращение продлевает) или явный `POST /api/lock`. Перебор запирается после 5 промахов на 5 минут, как админский PIN.\n\nХранение — `locks.json`, ключ ПУТЬ папки (как в избранном), пин — sha256 с солью: кэш уезжает в еженедельную копию разметки в Telegram, и коды оттуда читаться не должны. Замок едет за папкой — `locks.move` в `moveMemory` (переименование и переезд на другой диск) — и снимается в `trashPath` (`locks.forget`): иначе новая папка с тем же именем открылась бы по старому коду. Закрывать можно только папку (не корень библиотеки) и только в музыке и фото.\n\nАдминка: вкладка «Папки под кодом» и общий `pickFolder` — одно окно выбора папки на три дела (куда загрузить, где создать подпапку, какую закрыть). Кнопки «📁 Создать папку» / «📦 ZIP альбомом» / «📥 В папку…» в разделах музыки и фото, «📁 Создать подпапку» и «📥 Загрузить сюда» внутри папки. Бэкенд для этого был готов (`adminMkdir` умел корень и вложенность, `uploadFinish` — цели `into` и `into-zip`), не хватало кнопок. Одна правка по делу: каталог не показывает пустые папки, и только что созданная пропадала из админки — загрузить в неё было нечем; `adminOverview` теперь дополняет разделы музыки и фото папками с диска (`withEmpty`, флаг `empty` в `adminItem`), в списке они помечены «пусто». `/api/admin/children` отдаёт `library_kind` и `locked`.\n\nОдиннадцать тестов (`locks_test.go`): папка исчезает из списка и из каталога, прямая ссылка на файл внутри неё не работает, чужой код не открывает чужую папку, кука работает без заголовка и на картинках, замок переживает переименование, снимается с удалённой папкой, запрет на корень и на одинаковые коды, правила длины, «закрыть» и истечение по простою, запирание перебора, в списке замков нет ни кодов, ни хешей. Проверено вживую в браузере против стенда с музыкой и фото: создание папки, выбор папки для загрузки, загрузка файла в созданную папку, установка кода на подпапку, исчезновение её из альбома, открытие кодом (снимки грузятся) и «Закрыть».'
);
-- +goose StatementEnd

-- +goose Down
DELETE FROM releases WHERE version = '2.124.0';
